712	    int flags = 0;
713	    if (excludeDirectories) { flags = flags | ZIP_FL_NODIR; }
714	    if (!caseSensitive) { flags = flags | ZIP_FL_NOCASE; }
715	    if (state==Original) { flags = flags | LIBZIPPP_ORIGINAL_STATE_FLAGS; }
716	    else { flags = flags | ZIP_FL_ENC_GUESS; }
