743	ZipEntry ZipArchive::getEntry(libzippp_int64 index, State state) const {
744	    if (isOpen()) {
745	        struct zip_stat stat;
746	        zip_stat_init(&stat);
747	        int flag = state==Original ? LIBZIPPP_ORIGINAL_STATE_FLAGS : ZIP_FL_ENC_GUESS;
748	        int result = zip_stat_index(zipHandle, index, flag, &stat);
749	        if (result==0) {
750	            return createEntry(&stat);
751	        } else {
752	            //index not found / invalid index
753	        }
754	    }
755	    return ZipEntry();
756	}
