1044	void ZipArchive::releaseAdoptedBuffers(void) {
1045	    for(vector<void*>::iterator it=adoptedBuffers.begin() ; it!=adoptedBuffers.end() ; ++it) {
1046	        ::free(*it);
1047	    }
1048	    adoptedBuffers.clear();
1049	}
