1506	        char* data2 = (char*)malloc(6);
1507	        memcpy(data2, "WORLD", 6);
1508	        assert(z.addData("a/b.txt", data2, 5, true)); //replaces the previous buffer
1509	        assert(z.close() == LIBZIPPP_OK);
