// Verification of the compression configuration fixes (not part of the build).
#include <cassert>
#include <cstring>
#include <iostream>
#include "libzippp.h"

using namespace libzippp;
using namespace std;

int main(void) {
    // 1. archive default method must not mask existing entries; new files use the default
    {
        ZipArchive z1("v.zip");
        z1.open(ZipArchive::Write);
        assert(z1.addData("deflated.txt", "AAAA", 4));
        ZipEntry e = z1.getEntry("deflated.txt");
        assert(e.setCompressionMethod(DEFLATE));
        assert(z1.close() == LIBZIPPP_OK);

        ZipArchive z2("v.zip");
        z2.open(ZipArchive::Write);
        z2.setCompressionMethod(STORE); //archive default for SUBSEQUENT additions only
        ZipEntry old1 = z2.getEntry("deflated.txt");
        assert(old1.getCompressionMethod() == DEFLATE); //not masked by archive default
        ZipEntry old2 = z2.getEntry((libzippp_int64)0);
        assert(old2.getCompressionMethod() == DEFLATE);
        vector<ZipEntry> all = z2.getEntries();
        assert(all.size() == 1 && all[0].getCompressionMethod() == DEFLATE);
        assert(z2.addData("stored.txt", "BBBB", 4)); //added with the archive default
        ZipEntry st = z2.getEntry("stored.txt");
        assert(st.getCompressionMethod() == STORE);
        assert(z2.close() == LIBZIPPP_OK);

        ZipArchive z3("v.zip");
        z3.open(ZipArchive::ReadOnly);
        assert(z3.getEntry("deflated.txt").getCompressionMethod() == DEFLATE);
        ZipEntry s = z3.getEntry("stored.txt");
        assert(s.getCompressionMethod() == STORE); //recognized after reopen
        assert(s.readAsText() == "BBBB"); //full content readable
        z3.close();
    }

    // 2. Current vs Original: staged method/level visible in Current only
    {
        ZipArchive z1("v.zip");
        z1.open(ZipArchive::Write);
        ZipEntry cur = z1.getEntry("deflated.txt", false, true, ZipArchive::Current);
        ZipEntry ori = z1.getEntry("deflated.txt", false, true, ZipArchive::Original);
        assert(cur.getCompressionMethod() == DEFLATE);
        assert(ori.getCompressionMethod() == DEFLATE);
        assert(cur.getCompressionLevel() == 0); //original level not knowable
        assert(ori.getCompressionLevel() == 0);

        assert(cur.setCompressionMethod(STORE));
        assert(cur.setCompressionLevel(0));
        ZipEntry cur2 = z1.getEntry("deflated.txt");
        assert(cur2.getCompressionMethod() == STORE); //re-query reflects latest
        ZipEntry ori2 = z1.getEntry("deflated.txt", false, true, ZipArchive::Original);
        assert(ori2.getCompressionMethod() == DEFLATE); //original untouched
        assert(ori2.getCompressionLevel() == 0); //original never borrows the level

        ZipEntry lvl = z1.getEntry("deflated.txt");
        assert(lvl.setCompressionLevel(7));
        assert(lvl.getCompressionLevel() == 7);
        assert(lvl.getCompressionMethod() == STORE); //method preserved
        ZipEntry lvl2 = z1.getEntry("deflated.txt");
        assert(lvl2.getCompressionLevel() == 7); //Current query shows the staged level
        assert(lvl2.getCompressionMethod() == STORE);
        ZipEntry lvlO = z1.getEntry("deflated.txt", false, true, ZipArchive::Original);
        assert(lvlO.getCompressionLevel() == 0);
        assert(lvlO.getCompressionMethod() == DEFLATE);
        //by index and by listing too
        ZipEntry byIdx = z1.getEntry((libzippp_int64)lvl2.getIndex());
        assert(byIdx.getCompressionMethod() == STORE && byIdx.getCompressionLevel() == 7);
        vector<ZipEntry> all = z1.getEntries();
        bool found = false;
        for (size_t i = 0; i < all.size(); ++i) {
            if (all[i].getName() == "deflated.txt") {
                found = true;
                assert(all[i].getCompressionMethod() == STORE);
                assert(all[i].getCompressionLevel() == 7);
            }
        }
        assert(found);
        z1.discard();
    }

    // 3. multiple copies alternating: each setter preserves the other setting
    {
        ZipArchive z1("v.zip");
        z1.open(ZipArchive::Write);
        ZipEntry c1 = z1.getEntry("deflated.txt");
        ZipEntry c2 = z1.getEntry("deflated.txt");
        assert(c1.setCompressionMethod(STORE));
        assert(c2.setCompressionLevel(5)); //must preserve STORE, not c2's stale DEFLATE
        assert(c2.getCompressionMethod() == STORE);
        assert(c2.getCompressionLevel() == 5);
        ZipEntry check = z1.getEntry("deflated.txt");
        assert(check.getCompressionMethod() == STORE);
        assert(check.getCompressionLevel() == 5);
        assert(c1.setCompressionMethod(DEFLATE)); //must preserve level 5
        assert(c1.getCompressionMethod() == DEFLATE);
        assert(c1.getCompressionLevel() == 5);
        check = z1.getEntry("deflated.txt");
        assert(check.getCompressionMethod() == DEFLATE);
        assert(check.getCompressionLevel() == 5);
        //an already-obtained object may keep its old attributes
        //(c2 still shows STORE/5 here: no requirement to update it)

        //archive entry point setting both at once still works
        ZipEntry both = z1.getEntry("deflated.txt");
        assert(z1.setEntryCompressionConfig(both, DEFLATE, 3));
        assert(both.getCompressionMethod() == DEFLATE);
        assert(both.getCompressionLevel() == 3);
        assert(z1.getEntry("deflated.txt").getCompressionLevel() == 3);

        //rename keeps the staged settings on re-obtained entries
        assert(z1.renameEntry("deflated.txt", "renamed.txt") == 1);
        ZipEntry rn = z1.getEntry("renamed.txt");
        assert(rn.getCompressionMethod() == DEFLATE);
        assert(rn.getCompressionLevel() == 3);
        assert(z1.close() == LIBZIPPP_OK);

        //reopen: the recorded level is not carried over (not stored in the zip)
        ZipArchive z2("v.zip");
        z2.open(ZipArchive::ReadOnly);
        ZipEntry re = z2.getEntry("renamed.txt");
        assert(re.getCompressionMethod() == DEFLATE);
        assert(re.getCompressionLevel() == 0);
        assert(re.readAsText() == "AAAA");
        z2.close();
    }

    // 4. invalid level: entry call fails, nothing changes
    {
        ZipArchive z1("v.zip");
        z1.open(ZipArchive::Write);
        ZipEntry e = z1.getEntry("renamed.txt");
        assert(e.getCompressionMethod() == DEFLATE);
        assert(!e.setCompressionLevel(10)); //DEFLATE level 10 rejected
        assert(e.getCompressionMethod() == DEFLATE); //object unchanged
        assert(e.getCompressionLevel() == 0);
        ZipEntry re = z1.getEntry("renamed.txt");
        assert(re.getCompressionMethod() == DEFLATE); //archive unchanged
        assert(re.getCompressionLevel() == 0);
        assert(!z1.setEntryCompressionConfig(e, DEFLATE, 10));
        assert(e.getCompressionLevel() == 0);
        //valid boundary levels accepted
        assert(e.setCompressionLevel(1));
        assert(e.setCompressionLevel(9));
        assert(e.getCompressionLevel() == 9);
        z1.discard();
    }

    // 5. invalid archive default level: addition fails cleanly, pending changes preserved
    {
        ZipArchive z1("v.zip");
        z1.open(ZipArchive::Write);
        assert(z1.addData("pending.txt", "PP", 2));
        ZipEntry pe = z1.getEntry("renamed.txt");
        assert(pe.setCompressionMethod(STORE)); //staged change on existing entry
        z1.setCompressionMethod(DEFLATE);
        z1.setCompressionLevel(10); //invalid default level
        assert(!z1.addData("newdir/newfile.txt", "NN", 2)); //fails, no trace left
        assert(!z1.hasEntry("newdir/"));
        assert(!z1.hasEntry("newdir/newfile.txt"));
        assert(z1.hasEntry("pending.txt")); //pending addition preserved
        assert(z1.getEntry("renamed.txt").getCompressionMethod() == STORE); //staged setting preserved
        z1.setCompressionLevel(9); //fix the settings
        assert(z1.addData("newdir/newfile.txt", "NN", 2)); //and the addition works again
        assert(z1.getEntry("newdir/newfile.txt").getCompressionMethod() == DEFLATE);
        assert(z1.getEntry("newdir/newfile.txt").getCompressionLevel() == 9);
        assert(z1.close() == LIBZIPPP_OK);

        ZipArchive z2("v.zip");
        z2.open(ZipArchive::ReadOnly);
        assert(z2.getEntry("pending.txt").readAsText() == "PP");
        assert(z2.getEntry("newdir/newfile.txt").readAsText() == "NN");
        assert(z2.getEntry("renamed.txt").getCompressionMethod() == STORE);
        z2.close();
    }

    // 6. archive default level alone (no method) applies to the actual write
    {
        ZipArchive z1("v2.zip");
        z1.setCompressionLevel(8);
        z1.open(ZipArchive::Write);
        assert(z1.addData("lvl.txt", "LL", 2));
        ZipEntry e = z1.getEntry("lvl.txt");
        assert(e.getCompressionLevel() == 8); //explicitly chosen for this opening
        assert(z1.close() == LIBZIPPP_OK);

        ZipArchive z2("v2.zip");
        z2.open(ZipArchive::ReadOnly);
        ZipEntry e2 = z2.getEntry("lvl.txt");
        assert(e2.getCompressionMethod() == DEFLATE); //libzip default method
        assert(e2.getCompressionLevel() == 0); //level not stored in the zip
        assert(e2.readAsText() == "LL");
        z2.close();
        z2.unlink();
    }

    // 7. setCompressionLevel on a freshly added entry keeps the libzip default method
    {
        ZipArchive z1("v3.zip");
        z1.open(ZipArchive::Write);
        assert(z1.addData("fresh.txt", "FF", 2));
        ZipEntry e = z1.getEntry("fresh.txt");
        assert(e.setCompressionLevel(4));
        assert(e.getCompressionMethod() == DEFLATE); //default method preserved, not STORE
        assert(e.getCompressionLevel() == 4);
        assert(z1.close() == LIBZIPPP_OK);
        ZipArchive z2("v3.zip");
        z2.open(ZipArchive::ReadOnly);
        assert(z2.getEntry("fresh.txt").getCompressionMethod() == DEFLATE);
        assert(z2.getEntry("fresh.txt").readAsText() == "FF");
        z2.close();
        z2.unlink();
    }

    // 8. read-only / closed / old-session objects still reject modifications
    {
        ZipArchive z1("v.zip");
        z1.open(ZipArchive::ReadOnly);
        ZipEntry e = z1.getEntry("renamed.txt");
        assert(!e.setCompressionMethod(STORE));
        assert(!e.setCompressionLevel(2));
        z1.close();
        assert(!e.setCompressionMethod(STORE)); //expired session
        assert(!e.setCompressionLevel(2));

        z1.open(ZipArchive::Write);
        ZipEntry e2 = z1.getEntry("renamed.txt");
        assert(e2.setCompressionMethod(DEFLATE)); //new opening works
        assert(!e.setCompressionMethod(STORE)); //entry from the old opening still refused
        z1.close();
    }

    // 9. setEntryCompressionConfig with DEFAULT resets to libzip default
    {
        ZipArchive z1("v.zip");
        z1.open(ZipArchive::Write);
        ZipEntry e = z1.getEntry("renamed.txt");
        assert(z1.setEntryCompressionConfig(e, DEFAULT, 0));
        assert(e.getCompressionMethod() == DEFAULT);
        assert(z1.getEntry("renamed.txt").getCompressionMethod() == DEFAULT);
        assert(z1.close() == LIBZIPPP_OK);
        ZipArchive z2("v.zip");
        z2.open(ZipArchive::ReadOnly);
        assert(z2.getEntry("renamed.txt").getCompressionMethod() == DEFLATE);
        z2.close();
    }

    ZipArchive cleaner("v.zip");
    cleaner.unlink();

    cout << "all compression checks passed." << endl;
    return 0;
}

